#include <iostream>
#include <vector>
#include <iterator>
#include <algorithm>

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    // Create an ostream_iterator for integers, outputting to std::cout with space delimiter
    std::ostream_iterator<int> out_it(std::cout, " ");
    // Use std::copy to output the range of numbers to std::cout
    std::copy(numbers.begin(), numbers.end(), out_it);
    std::cout << std::endl;
    return 0;
}
